                                                                FROM (SELECT "t45"."line_id", "t45"."request_number", "t45"."line_no", "t45"."item", "t45"."quantity", "t45"."unit_price", "t45"."reason", "t45"."requested_resolution", "t45"."requested_variant", "t45"."state", "t45"."way", "t45"."customer", "t45"."customer0", "t45"."order_number", "t45"."channel", "t45"."requested_date", "t45"."state0", "customer8"."customer_id", "customer8"."addr", "customer8"."cdemo", "customer8"."hdemo", "customer8"."birth_year", "customer8"."center", "customer8"."email"
                                                                        FROM (SELECT "return_request_line6"."line_id", "return_request_line6"."request_number", "return_request_line6"."line_no", "return_request_line6"."item", "return_request_line6"."quantity", "return_request_line6"."unit_price", "return_request_line6"."reason", "return_request_line6"."requested_resolution", "return_request_line6"."requested_variant", "return_request_line6"."state", "return_request_line6"."way", "return_request_line6"."customer", "return_request6"."customer" AS "customer0", "return_request6"."order_number", "return_request6"."channel", "return_request6"."requested_date", "return_request6"."state" AS "state0"
                                                                                FROM "return_request_line" AS "return_request_line6"
                                                                                    INNER JOIN "return_request" AS "return_request6" ON "return_request_line6"."request_number" = "return_request6"."request_number") AS "t45"
                                                                            LEFT JOIN "customer" AS "customer8" ON "t45"."customer" = "customer8"."sk") AS "t46"
                                                                WHERE "t46"."state" = 'received') AS "t48"
                                                            INNER JOIN "customer" AS "customer9" ON "t48"."customer" = "customer9"."sk") AS "t49"
                                                    LEFT JOIN "inventory" AS "inventory3" ON "t49"."item" = "inventory3"."item" AND "t49"."center" = "inventory3"."warehouse"
                                                GROUP BY CASE WHEN "t49"."line_id" IS NULL THEN 'n' ELSE 'v' || CAST("t49"."line_id" AS VARCHAR) END) AS "t51" ON "t44"."_ttrp_g_n34_0" = "t51"."_ttrp_g_n34_0" AND "t44"."as_of_date" = "t51"."_ttrp_latest_n34") AS "t52"
                                    LEFT JOIN "inventory" AS "inventory4" ON "t52"."requested_variant" = "inventory4"."item" AND "t52"."center" = "inventory4"."warehouse"
                                GROUP BY CASE WHEN "t52"."line_id" IS NULL THEN 'n' ELSE 'v' || CAST("t52"."line_id" AS VARCHAR) END) AS "t54" ON "t38"."_ttrp_g_n37_0" = "t54"."_ttrp_g_n37_0" AND "t38"."as_of_date" = "t54"."_ttrp_latest_n37") AS "t55" ON "t23"."line_id" = "t55"."line_id") AS "t56"
            LEFT JOIN (SELECT "request_number", SUM("quantity" * "unit_price") AS "request_value"
                FROM "return_request_line"
                GROUP BY "request_number") AS "t59" ON "t56"."request_number" = "t59"."request_number") AS "t60"
WHERE "t60"."route" = 'reject_abuse'
